        entry(.overview, "overview", "enabled", tr("Activer la vue d’ensemble", "Turn on the overview"), tr("Carte globale des écrans, bureaux et stages Roadie, accessible par la CLI, BetterTouchTool ou un raccourci facultatif.", "Global map of Roadie displays, desktops and stages, reachable through the CLI, BetterTouchTool or an optional shortcut."), .bool, .bool(true)),
        entry(.overview, "overview", "presentation", tr("Disposition", "Layout"), tr("Archipel : écrans en colonnes et bureaux en îlots. Baies : écrans en bandes et bureaux côte à côte. Les traits obliques séparent les écrans.", "Archipelago: displays in columns and desktops as islands. Bays: displays in bands and desktops side by side. Slanted lines separate the displays."), .choice(["archipelago", "bays"]), .string("archipelago")),
        entry(.overview, "overview", "loupe", tr("Loupe au survol", "Magnify on hover"), tr("Agrandit les cartes du bureau sous la souris après une courte stabilisation. Consulter ne change pas le bureau actif. Désactivez pour garder la même taille partout.", "Enlarges the cards of the desktop under the mouse after a short pause. Looking does not change the active desktop. Turn off to keep the same size everywhere."), .bool, .bool(true)),
        entry(.overview, "overview", "magnification", tr("Grossissement de la loupe (%)", "Magnification (%)"), tr("Taille des cartes du bureau survolé, par rapport aux autres. Les autres bureaux se resserrent si la place manque et restent visibles. Aucune fenêtre n’est redimensionnée.", "Size of the hovered desktop's cards compared with the others. Other desktops tighten if space runs short and stay visible. No window is resized."), .double(100...250), .double(150)),
        entry(.overview, "overview", "background_blur", tr("Flou du fond d’écran (%)", "Wallpaper blur (%)"), tr("0 % : fond d’écran net. 100 % : très flou. L’aperçu montre votre fond d’écran avec ce réglage. Le flou masque les icônes du bureau sans gêner la lecture des cartes.", "0%: sharp wallpaper. 100%: very blurred. The preview shows your wallpaper with this setting. The blur hides desktop icons without hurting card readability."), .double(0...100), .double(20)),
        entry(.overview, "overview", "selection_color", tr("Couleur du contour de sélection", "Selection outline color"), tr("Contour de la fenêtre sélectionnée : au départ la fenêtre active, puis celle choisie aux flèches. C’est la fenêtre qu’Entrée ouvre. Le survol de la souris ne la déplace pas.", "Outline of the selected window: the active window at first, then the one chosen with the arrow keys. It is the window Return opens. Hovering with the mouse does not move it."), .color, .string("#66C2F7")),
        entry(.overview, "overview", "selection_width", tr("Épaisseur du contour de sélection (points)", "Selection outline width (points)"), tr("Épaisseur du contour de la fenêtre sélectionnée, de 1 à 8 points.", "Width of the selected window's outline, from 1 to 8 points."), .double(1...8), .double(2)),
        entry(.raccourcis, "overview", "hotkey", tr("Raccourci de la vue d’ensemble", "Overview shortcut"), tr("Enregistrez directement une combinaison. Laissez vide pour BetterTouchTool, Karabiner ou un autre outil : roadie overview toggle. Ce réglage ne modifie pas Cmd+Tab.", "Record a key combination directly. Leave empty for BetterTouchTool, Karabiner or another tool: roadie overview toggle. This setting does not change Cmd+Tab."), .text, .string("")),
